Future<void> _reseau(String nom, String url) async {
  if (url.isEmpty) {
    _message('La page ' + nom + ' de Léxi arrive bientôt 🦊');
    return;
  }
  await launchURL(url);
}

Future<void> _contacter() async {
  final e = (widget.emailContact ?? '').trim();
  final champ = TextEditingController();
  final envoyer = await showDialog<bool>(
    context: context,
    builder: (ctx) => AlertDialog(
      backgroundColor: p.carte,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      title: Text("Contacter l'assistance",
          style: TextStyle(color: p.texte, fontWeight: FontWeight.w800)),
      content: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(_u?.email ?? '', style: TextStyle(color: p.gris, fontSize: 13)),
          SizedBox(height: 10),
          TextField(
            controller: champ,
            maxLines: 5,
            style: TextStyle(color: p.texte),
            decoration: InputDecoration(
              hintText: 'Ton message',
              hintStyle: TextStyle(color: p.indice),
              filled: true,
              fillColor: p.puce,
              border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                  borderSide: BorderSide.none),
            ),
          ),
        ],
      ),
      actions: [
        TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text('Annuler', style: TextStyle(color: p.gris))),
        TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: Text('Envoyer',
                style: TextStyle(
                    color: _orange, fontWeight: FontWeight.bold))),
      ],
    ),
  );
  final texte = champ.text.trim();
  if (envoyer != true || texte.isEmpty) return;
  if (e.isNotEmpty) {
    await launchURL('mailto:' +
        e +
        '?subject=' +
        Uri.encodeComponent('Léxi - assistance') +
        '&body=' +
        Uri.encodeComponent(texte));
  }
  _message('Merci ! Ton message a bien été envoyé 🦊');
}

